```tsx
import "./ChipFilter.css";

export interface ChipOption<T extends string = string> {
  value: T;
  label: string;
}

export interface ChipFilterProps<T extends string = string> {
  label: string;
  options: readonly ChipOption<T>[];
  selected: readonly T[];
  onToggle: (value: T) => void;
}

export function ChipFilter<T extends string = string>({
  label,
  options,
  selected,
  onToggle,
}: ChipFilterProps<T>) {
  return (
    <fieldset className="chip-filter">
      <legend className="chip-filter__label">{label}</legend>
      <div className="chip-filter__chips">
        {options.map((option) => {
          const pressed = selected.includes(option.value);
          return (
            <button
              key={option.value}
              type="button"
              className="chip-filter__chip"
              aria-pressed={pressed}
              data-selected={pressed ? "true" : undefined}
              onClick={() => onToggle(option.value)}
            >
              <span className="chip-filter__mark" aria-hidden="true">
                {pressed ? "✓" : ""}
              </span>
              <span className="chip-filter__text">{option.label}</span>
            </button>
          );
        })}
      </div>
    </fieldset>
  );
}
