.chip-filter {
  margin: 0;
  padding: 0;
  border: 0;
  min-width: 0;
  font-family: inherit;
}

.chip-filter__label {
  padding: 0;
  margin-bottom: 0.5rem;
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--chip-fg-label);
}

.chip-filter__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.chip-filter__chip {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  min-height: 2.25rem;
  padding: 0.375rem 0.875rem;
  border: 1px solid var(--chip-border);
  border-radius: 999px;
  background: var(--chip-bg);
  color: var(--chip-fg);
  font: inherit;
  font-size: 0.9375rem;
  line-height: 1.2;
  cursor: pointer;
  user-select: none;
  transition:
    background-color 150ms ease,
    border-color 150ms ease,
    color 150ms ease,
    box-shadow 150ms ease;
}

.chip-filter__chip:hover {
  background: var(--chip-bg-hover);
}

.chip-filter__chip[data-selected="true"] {
  background: var(--chip-bg-selected);
  border-color: var(--chip-border-selected);
  color: var(--chip-fg-selected);
  box-shadow: var(--chip-shadow-selected);
}

.chip-filter__chip[data-selected="true"]:hover {
  filter: brightness(1.05);
}

.chip-filter__chip:focus {
  outline: none;
}

.chip-filter__chip:focus-visible {
  outline: 2px solid var(--chip-focus);
  outline-offset: 2px;
}

.chip-filter__mark {
  display: inline-block;
  width: 0.75em;
  font-size: 0.8125rem;
  font-weight: 700;
  text-align: center;
  line-height: 1;
}

.chip-filter__chip:not([data-selected="true"]) .chip-filter__mark {
  visibility: hidden;
}

@media (prefers-reduced-motion: reduce) {
  .chip-filter__chip {
    transition: none;
  }
}
